35: /* Defrag helper for generic allocations.
36:  *
37:  * returns NULL in case the allocation wasn't moved.
38:  * when it returns a non-null value, the old pointer was already released
39:  * and should NOT be accessed. */
40: void* activeDefragAlloc(void *ptr) {
41:     size_t size;
42:     void *newptr;
43:     if(!je_get_defrag_hint(ptr)) {
44:         server.stat_active_defrag_misses++;
45:         return NULL;
46:     }
47:     /* move this allocation to a new allocation.
48:      * make sure not to use the thread cache. so that we don't get back the same
49:      * pointers we try to free */
50:     size = zmalloc_usable_size(ptr);
51:     newptr = zmalloc_no_tcache(size);
52:     memcpy(newptr, ptr, size);
53:     zfree_no_tcache(ptr);
54:     server.stat_active_defrag_hits++;
55:     return newptr;
56: }
