403: /* returns 0 if no more work needs to be been done, and 1 if time is up and more work is needed. */
404: long scanLaterList(robj *ob, unsigned long *cursor, long long endtime) {
405:     quicklist *ql = ob->ptr;
406:     quicklistNode *node;
407:     long iterations = 0;
408:     int bookmark_failed = 0;
409:     if (ob->type != OBJ_LIST || ob->encoding != OBJ_ENCODING_QUICKLIST)
410:         return 0;
411: 
412:     if (*cursor == 0) {
413:         /* if cursor is 0, we start new iteration */
414:         node = ql->head;
415:     } else {
416:         node = quicklistBookmarkFind(ql, "_AD");
417:         if (!node) {
418:             /* if the bookmark was deleted, it means we reached the end. */
419:             *cursor = 0;
420:             return 0;
421:         }
422:         node = node->next;
423:     }
424: 
425:     (*cursor)++;
426:     while (node) {
427:         activeDefragQuickListNode(ql, &node);
428:         server.stat_active_defrag_scanned++;
429:         if (++iterations > 128 && !bookmark_failed) {
430:             if (ustime() > endtime) {
431:                 if (!quicklistBookmarkCreate(&ql, "_AD", node)) {
432:                     bookmark_failed = 1;
433:                 } else {
434:                     ob->ptr = ql; /* bookmark creation may have re-allocated the quicklist */
435:                     return 1;
436:                 }
437:             }
438:             iterations = 0;
439:         }
440:         node = node->next;
441:     }
442:     quicklistBookmarkDelete(ql, "_AD");
443:     *cursor = 0;
444:     return bookmark_failed? 1: 0;
445: }
