588:     stream *s = ob->ptr;
589:     raxStart(&ri,s->rax);
590:     if (*cursor == 0) {
591:         /* if cursor is 0, we start new iteration */
592:         defragRaxNode(&s->rax->head);
593:         /* assign the iterator node callback before the seek, so that the
594:          * initial nodes that are processed till the first item are covered */
595:         ri.node_cb = defragRaxNode;
