609:     (*cursor)++;
610:     while (raxNext(&ri)) {
611:         void *newdata = activeDefragAlloc(ri.data);
612:         if (newdata)
613:             raxSetData(ri.node, ri.data=newdata);
614:         server.stat_active_defrag_scanned++;
615:         if (++iterations > 128) {
616:             if (ustime() > endtime) {
617:                 serverAssert(ri.key_len==sizeof(last));
618:                 memcpy(last,ri.key,ri.key_len);
619:                 raxStop(&ri);
620:                 return 1;
